from pathlib import Path
for candidate in (
    'tools/development/improvement_candidate_writer.py',
    'tools/development/workflow_ledger_verify.py',
    'tests/test_improvement_candidate_writer.py',
    'tests/test_workflow_ledger_verify.py',
):
    print(candidate, 'exists', Path(candidate).exists())
hits = []
for base in ('tools', 'tests'):
    for path in sorted(Path(base).rglob('*.py')):
        try:
            text = path.read_text(encoding='utf-8')
        except (OSError, UnicodeDecodeError):
            continue
        if 'workflow_ledger' in text or 'improvement_candidate_writer' in text:
            hits.append(path.as_posix())
print('name_hits', hits)
